SELECT collection_name FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA ORDER BY Subjects DESC LIMIT 5;
SELECT collection_name FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA GROUP BY collection_name HAVING COUNT(DISTINCT ImageTypes) > 1;
SELECT ImageTypes, collection_name FROM ( SELECT ImageTypes, collection_name, Subjects, ROW_NUMBER() OVER (PARTITION BY ImageTypes ORDER BY Subjects DESC) AS rn FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA ) t WHERE rn = 1;
SELECT collection_name FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA WHERE Subjects > (SELECT AVG(Subjects) FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA);
SELECT collection_name FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA WHERE collection_name IN (SELECT project_short_name FROM IDC.IDC_V17_TCGA_BIOSPECIMEN_REL9);
SELECT collection_name FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA t1 WHERE Subjects > (SELECT AVG(Subjects) FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA t2 WHERE t2.ImageTypes = t1.ImageTypes);
SELECT sample_type, project_short_name FROM ( SELECT sample_type, project_short_name, days_to_collection, ROW_NUMBER() OVER (PARTITION BY sample_type ORDER BY days_to_collection DESC) AS rn FROM IDC.IDC_V17_TCGA_BIOSPECIMEN_REL9 ) t WHERE rn = 1;
WITH base AS ( SELECT project_short_name AS Entity, days_to_collection AS Time, num_portions AS Measure, LAG(num_portions, 1) OVER (PARTITION BY project_short_name ORDER BY days_to_collection) AS prev1, LAG(num_portions, 2) OVER (PARTITION BY project_short_name ORDER BY days_to_collection) AS prev2 FROM IDC.IDC_V17_TCGA_BIOSPECIMEN_REL9 WHERE days_to_collection IS NOT NULL AND num_portions IS NOT NULL ) SELECT DISTINCT Entity FROM base WHERE prev2 IS NOT NULL AND Measure > prev1 AND prev1 > prev2;
WITH ranked AS ( SELECT ImageTypes AS Category, collection_name AS Entity, Subjects AS Measure, NTILE(5) OVER (PARTITION BY ImageTypes ORDER BY Subjects DESC) AS quintile FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA WHERE Subjects IS NOT NULL ) SELECT Category, Entity FROM ranked WHERE quintile = 1;
WITH category_stats AS ( SELECT ImageTypes AS Category, AVG(Subjects) AS avg_measure, SUM(Subjects) AS total_measure FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA GROUP BY ImageTypes ), ranked AS ( SELECT t.ImageTypes AS Category, t.collection_name AS Entity, t.Subjects AS Measure, cs.avg_measure, cs.total_measure, t.Subjects / cs.total_measure * 100 AS pct_of_total, ROW_NUMBER() OVER (PARTITION BY t.ImageTypes ORDER BY t.Subjects / cs.total_measure DESC) AS rn FROM IDC.IDC_V17_ORIGINAL_COLLECTIONS_METADATA t JOIN category_stats cs ON t.ImageTypes = cs.Category WHERE t.Subjects > cs.avg_measure ) SELECT Category, Entity, pct_of_total FROM ranked WHERE rn <= 5;
WITH lagged AS ( SELECT sample_type AS Category, project_short_name AS Entity, days_to_collection AS Time, num_portions AS Measure, LAG(num_portions) OVER (PARTITION BY sample_type, project_short_name ORDER BY days_to_collection) AS prev_measure FROM IDC.IDC_V17_TCGA_BIOSPECIMEN_REL9 WHERE num_portions IS NOT NULL AND days_to_collection IS NOT NULL ), growth AS ( SELECT Category, Entity, Time, (Measure - prev_measure) / NULLIF(prev_measure, 0) * 100 AS growth_rate FROM lagged WHERE prev_measure IS NOT NULL AND prev_measure > 0 ), ranked AS ( SELECT Category, Entity, growth_rate, ROW_NUMBER() OVER (PARTITION BY Category ORDER BY growth_rate DESC) AS rn FROM growth ) SELECT Category, Entity, growth_rate FROM ranked WHERE rn <= 5;
SELECT name FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS ORDER BY capacity DESC LIMIT 5;
SELECT rental_methods, name FROM ( SELECT rental_methods, name, capacity, ROW_NUMBER() OVER (PARTITION BY rental_methods ORDER BY capacity DESC) AS rn FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS ) t WHERE rn = 1;
SELECT name FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS WHERE capacity > (SELECT AVG(capacity) FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS);
SELECT DISTINCT name FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS s WHERE NOT EXISTS ( SELECT 1 FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_TRIPS t WHERE t.start_station_id = s.station_id );
SELECT name FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS WHERE station_id IN (SELECT start_station_id FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_TRIPS);
SELECT name FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS t1 WHERE capacity > (SELECT AVG(capacity) FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS t2 WHERE t2.rental_methods = t1.rental_methods);
WITH sorted_values AS ( SELECT rental_methods, capacity FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS ORDER BY rental_methods, capacity ), method_arrays AS ( SELECT rental_methods, JSON_ARRAYAGG(capacity) AS values_array, COUNT(*) AS cnt FROM sorted_values GROUP BY rental_methods ), method_percentiles AS ( SELECT rental_methods, IF( ABS((cnt-1)*0.3 - FLOOR((cnt-1)*0.3)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.3), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.3), ']')) * (1 - ((cnt-1)*0.3 - FLOOR((cnt-1)*0.3))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.3), ']')) * (((cnt-1)*0.3 - FLOOR((cnt-1)*0.3))) ) AS p30, IF( ABS((cnt-1)*0.7 - FLOOR((cnt-1)*0.7)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.7), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.7), ']')) * (1 - ((cnt-1)*0.7 - FLOOR((cnt-1)*0.7))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.7), ']')) * (((cnt-1)*0.7 - FLOOR((cnt-1)*0.7))) ) AS p70 FROM method_arrays ) SELECT t.rental_methods, t.name, t.capacity, t.station_id, t.latitude, t.longitude FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS t JOIN method_percentiles mp ON t.rental_methods = mp.rental_methods WHERE t.capacity BETWEEN mp.p30 AND mp.p70;
WITH yearly_records AS ( SELECT DISTINCT usertype AS Category, start_station_id AS Entity, EXTRACT(YEAR FROM CAST(starttime AS DATETIME)) AS Time FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_TRIPS WHERE starttime IS NOT NULL ), with_prev AS ( SELECT Category, Entity, Time, LAG(Time) OVER (PARTITION BY Category, Entity ORDER BY Time) AS prev_time FROM yearly_records ) SELECT DISTINCT Category, Entity FROM with_prev WHERE prev_time IS NOT NULL AND Time - prev_time = 1;
WITH ranked AS ( SELECT rental_methods AS Category, name AS Entity, capacity AS Measure, NTILE(5) OVER (PARTITION BY rental_methods ORDER BY capacity DESC) AS quintile FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS WHERE capacity IS NOT NULL ) SELECT Category, Entity FROM ranked WHERE quintile = 1;
WITH category_stats AS ( SELECT rental_methods AS Category, AVG(capacity) AS avg_measure, SUM(capacity) AS total_measure FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS GROUP BY rental_methods ), ranked AS ( SELECT t.rental_methods AS Category, t.name AS Entity, t.capacity AS Measure, cs.avg_measure, cs.total_measure, t.capacity / cs.total_measure * 100 AS pct_of_total, ROW_NUMBER() OVER (PARTITION BY t.rental_methods ORDER BY t.capacity / cs.total_measure DESC) AS rn FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS t JOIN category_stats cs ON t.rental_methods = cs.Category WHERE t.capacity > cs.avg_measure ) SELECT Category, Entity, pct_of_total FROM ranked WHERE rn <= 5;
WITH sorted_values AS ( SELECT rental_methods, capacity FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS ORDER BY rental_methods, capacity ), category_arrays AS ( SELECT rental_methods, JSON_ARRAYAGG(capacity) AS values_array, COUNT(*) AS cnt FROM sorted_values GROUP BY rental_methods ), category_median AS ( SELECT rental_methods, IF( ABS((cnt-1)*0.5 - FLOOR((cnt-1)*0.5)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.5), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.5), ']')) * (1 - ((cnt-1)*0.5 - FLOOR((cnt-1)*0.5))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.5), ']')) * (((cnt-1)*0.5 - FLOOR((cnt-1)*0.5))) ) AS median_capacity FROM category_arrays ) SELECT t.rental_methods, t.name, t.capacity, t.station_id, t.latitude, t.longitude FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS t JOIN category_median m ON t.rental_methods = m.rental_methods WHERE t.capacity > m.median_capacity AND EXISTS ( SELECT 1 FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_TRIPS tr WHERE tr.start_station_id = t.station_id );
WITH method_avg AS ( SELECT rental_methods AS Category, AVG(capacity) AS avg_capacity FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS GROUP BY rental_methods ), ranked AS ( SELECT t.rental_methods AS Category, t.name AS Entity, t.capacity AS Measure, ma.avg_capacity, (t.capacity - ma.avg_capacity) / ma.avg_capacity * 100 AS pct_above_avg, t.station_id, t.latitude, t.longitude, ROW_NUMBER() OVER (PARTITION BY t.rental_methods ORDER BY t.capacity DESC) AS rn FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_STATIONS t JOIN method_avg ma ON t.rental_methods = ma.Category WHERE t.capacity IS NOT NULL ) SELECT Category, Entity, Measure, avg_capacity, pct_above_avg, station_id, latitude, longitude FROM ranked WHERE rn <= 3;
SELECT Population_ID FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA ORDER BY HetRateAuto DESC LIMIT 5;
SELECT Population_ID FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA GROUP BY Population_ID HAVING COUNT(DISTINCT Gender) > 1;
SELECT Gender, Population_ID FROM ( SELECT Gender, Population_ID, HetRateAuto, ROW_NUMBER() OVER (PARTITION BY Gender ORDER BY HetRateAuto DESC) AS rn FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA ) t WHERE rn = 1;
SELECT Population_ID FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA WHERE HetRateAuto > (SELECT AVG(HetRateAuto) FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA);
SELECT Population_ID FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA t1 WHERE HetRateAuto > (SELECT AVG(HetRateAuto) FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA t2 WHERE t2.Gender = t1.Gender);
WITH sorted_values AS ( SELECT Gender, HetRateAuto FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA ORDER BY Gender, HetRateAuto ), gender_arrays AS ( SELECT Gender, JSON_ARRAYAGG(HetRateAuto) AS values_array, COUNT(*) AS cnt FROM sorted_values GROUP BY Gender ), gender_percentiles AS ( SELECT Gender, CAST(IF( ABS((cnt-1)*0.3 - FLOOR((cnt-1)*0.3)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.3), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.3), ']')) * (1 - ((cnt-1)*0.3 - FLOOR((cnt-1)*0.3))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.3), ']')) * (((cnt-1)*0.3 - FLOOR((cnt-1)*0.3))) ) AS FLOAT) AS p30, CAST(IF( ABS((cnt-1)*0.7 - FLOOR((cnt-1)*0.7)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.7), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.7), ']')) * (1 - ((cnt-1)*0.7 - FLOOR((cnt-1)*0.7))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.7), ']')) * (((cnt-1)*0.7 - FLOOR((cnt-1)*0.7))) ) AS FLOAT) AS p70 FROM gender_arrays ) SELECT t.Gender, t.Population_ID, t.HetRateAuto, t.Region, t.Country FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA t JOIN gender_percentiles gp ON t.Gender = gp.Gender WHERE t.HetRateAuto BETWEEN LEAST(gp.p30, gp.p70) AND GREATEST(gp.p30, gp.p70);
WITH ranked AS ( SELECT Gender AS Category, Population_ID AS Entity, HetRateAuto AS Measure, NTILE(5) OVER (PARTITION BY Gender ORDER BY HetRateAuto DESC) AS quintile FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA WHERE HetRateAuto IS NOT NULL ) SELECT Category, Entity FROM ranked WHERE quintile = 1;
WITH category_stats AS ( SELECT Gender AS Category, AVG(HetRateAuto) AS avg_measure, SUM(HetRateAuto) AS total_measure FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA GROUP BY Gender ), ranked AS ( SELECT t.Gender AS Category, t.Population_ID AS Entity, t.HetRateAuto AS Measure, cs.avg_measure, cs.total_measure, t.HetRateAuto / cs.total_measure * 100 AS pct_of_total, ROW_NUMBER() OVER (PARTITION BY t.Gender ORDER BY t.HetRateAuto / cs.total_measure DESC) AS rn FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA t JOIN category_stats cs ON t.Gender = cs.Category WHERE t.HetRateAuto > cs.avg_measure ) SELECT Category, Entity, pct_of_total FROM ranked WHERE rn <= 5;
WITH gender_avg AS ( SELECT Gender AS Category, AVG(HetRateAuto) AS avg_het FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA GROUP BY Gender ), ranked AS ( SELECT t.Gender AS Category, t.Population_ID AS Entity, t.HetRateAuto AS Measure, ga.avg_het, (t.HetRateAuto - ga.avg_het) / ga.avg_het * 100 AS pct_above_avg, t.Region, t.Country, ROW_NUMBER() OVER (PARTITION BY t.Gender ORDER BY t.HetRateAuto DESC) AS rn FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA t JOIN gender_avg ga ON t.Gender = ga.Category WHERE t.HetRateAuto IS NOT NULL ) SELECT Category, Entity, Measure, avg_het, pct_above_avg, Region, Country FROM ranked WHERE rn <= 3;
SELECT Region AS Category, SUM(HetRateAuto) AS total_het FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA GROUP BY Region ORDER BY total_het DESC LIMIT 3;
SELECT Region AS Category, COUNT(*) AS record_count FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA GROUP BY Region ORDER BY record_count DESC LIMIT 3;
WITH region_q3 AS ( SELECT Region AS Category, MIN(HetRateAuto) AS q3 FROM ( SELECT Region, HetRateAuto, PERCENT_RANK() OVER (PARTITION BY Region ORDER BY HetRateAuto) AS pr FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA ) t WHERE pr >= 0.75 GROUP BY Region ) SELECT t.Region, t.Population_ID, t.HetRateAuto, t.Country FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA t JOIN region_q3 q ON t.Region = q.Category WHERE t.HetRateAuto > q.q3;
SELECT Gene FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002 ORDER BY Expr DESC LIMIT 5;
SELECT case_barcode FROM TCGA_HG38_DATA_V0.TCGA_BIOCLIN_V0_ANNOTATIONS GROUP BY case_barcode HAVING COUNT(DISTINCT category) > 1;
SELECT Gene FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002 WHERE Expr > (SELECT AVG(Expr) FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002);
SELECT DISTINCT case_barcode FROM TCGA_HG38_DATA_V0.TCGA_BIOCLIN_V0_CLINICAL c WHERE NOT EXISTS ( SELECT 1 FROM TCGA_HG38_DATA_V0.TCGA_BIOCLIN_V0_ANNOTATIONS a WHERE a.case_barcode = c.case_barcode );
SELECT case_barcode FROM TCGA_HG38_DATA_V0.TCGA_BIOCLIN_V0_CLINICAL WHERE case_barcode IN (SELECT case_barcode FROM TCGA_HG38_DATA_V0.TCGA_BIOCLIN_V0_ANNOTATIONS);
WITH ranked AS ( SELECT project_short_name AS Category, Gene AS Entity, Expr AS Measure, NTILE(5) OVER (PARTITION BY project_short_name ORDER BY Expr DESC) AS quintile FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002 WHERE Expr IS NOT NULL ) SELECT Category, Entity FROM ranked WHERE quintile = 1;
WITH sorted_values AS ( SELECT project_short_name, Expr FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002 ORDER BY project_short_name, Expr ), category_arrays AS ( SELECT project_short_name, JSON_ARRAYAGG(Expr) AS values_array, COUNT(*) AS cnt FROM sorted_values GROUP BY project_short_name ), category_median AS ( SELECT project_short_name, IF( ABS((cnt-1)*0.5 - FLOOR((cnt-1)*0.5)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.5), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.5), ']')) * (1 - ((cnt-1)*0.5 - FLOOR((cnt-1)*0.5))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.5), ']')) * (((cnt-1)*0.5 - FLOOR((cnt-1)*0.5))) ) AS median_expr FROM category_arrays ) SELECT t.project_short_name, t.Gene, t.Expr, t.ID, t.Expr AS expression_level FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002 t JOIN category_median m ON t.project_short_name = m.project_short_name WHERE t.Expr > m.median_expr AND EXISTS ( SELECT 1 FROM TCGA_HG38_DATA_V0.TCGA_HG38_DATA_V0_PROTEIN_EXPRESSION p WHERE p.gene_name = t.Gene );
SELECT project_short_name AS Category, SUM(Expr) AS total_expr FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002 GROUP BY project_short_name ORDER BY total_expr DESC LIMIT 3;
SELECT data_category AS Category, COUNT(*) AS record_count FROM TCGA_HG38_DATA_V0.TCGA_HG38_DATA_V0_TCGA_METADATA_DATA_HG38_R14 GROUP BY data_category ORDER BY record_count DESC LIMIT 3;
WITH proj_q3 AS ( SELECT project_short_name AS Category, MIN(Expr) AS q3 FROM ( SELECT project_short_name, Expr, PERCENT_RANK() OVER (PARTITION BY project_short_name ORDER BY Expr) AS pr FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002 ) t WHERE pr >= 0.75 GROUP BY project_short_name ) SELECT t.project_short_name, t.Gene, t.Expr, t.ID FROM TCGA_HG38_DATA_V0.QOTM_PAAD_KIRP_RANDOM_SAMPLE_1002 t JOIN proj_q3 q ON t.project_short_name = q.Category WHERE t.Expr > q.q3;
SELECT PatientID FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 GROUP BY PatientID HAVING COUNT(DISTINCT Modality) > 1;
SELECT Modality, PatientID FROM ( SELECT Modality, PatientID, SliceThickness, ROW_NUMBER() OVER (PARTITION BY Modality ORDER BY SliceThickness DESC) AS rn FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 ) t WHERE rn = 1;
SELECT PatientID FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 t1 WHERE SliceThickness > (SELECT AVG(SliceThickness) FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 t2 WHERE t2.Modality = t1.Modality);
SELECT Modality, PatientID FROM ( SELECT Modality, PatientID, AcquisitionDate, ROW_NUMBER() OVER (PARTITION BY Modality ORDER BY AcquisitionDate DESC) AS rn FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 ) t WHERE rn = 1;
WITH sorted_values AS ( SELECT Modality, SliceThickness FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 ORDER BY Modality, SliceThickness ), modality_arrays AS ( SELECT Modality, JSON_ARRAYAGG(SliceThickness) AS values_array, COUNT(*) AS cnt FROM sorted_values GROUP BY Modality ), modality_percentiles AS ( SELECT Modality, IF( ABS((cnt-1)*0.3 - FLOOR((cnt-1)*0.3)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.3), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.3), ']')) * (1 - ((cnt-1)*0.3 - FLOOR((cnt-1)*0.3))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.3), ']')) * (((cnt-1)*0.3 - FLOOR((cnt-1)*0.3))) ) AS p30, IF( ABS((cnt-1)*0.7 - FLOOR((cnt-1)*0.7)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.7), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.7), ']')) * (1 - ((cnt-1)*0.7 - FLOOR((cnt-1)*0.7))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.7), ']')) * (((cnt-1)*0.7 - FLOOR((cnt-1)*0.7))) ) AS p70 FROM modality_arrays ) SELECT t.Modality, t.PatientID, t.SliceThickness, t.StudyDate, t.SeriesDescription FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 t JOIN modality_percentiles mp ON t.Modality = mp.Modality WHERE t.SliceThickness BETWEEN mp.p30 AND mp.p70;
WITH yearly_records AS ( SELECT DISTINCT Modality AS Category, PatientID AS Entity, EXTRACT(YEAR FROM AcquisitionDate) AS Time FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 WHERE AcquisitionDate IS NOT NULL ), with_prev AS ( SELECT Category, Entity, Time, LAG(Time) OVER (PARTITION BY Category, Entity ORDER BY Time) AS prev_time FROM yearly_records ) SELECT DISTINCT Category, Entity FROM with_prev WHERE prev_time IS NOT NULL AND Time - prev_time = 1;
WITH modality_avg AS ( SELECT Modality AS Category, AVG(SliceThickness) AS avg_thickness FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 GROUP BY Modality ), ranked AS ( SELECT t.Modality AS Category, t.PatientID AS Entity, t.SliceThickness AS Measure, ma.avg_thickness, (t.SliceThickness - ma.avg_thickness) / ma.avg_thickness * 100 AS pct_above_avg, t.StudyDate, t.SeriesDescription, ROW_NUMBER() OVER (PARTITION BY t.Modality ORDER BY t.SliceThickness DESC) AS rn FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 t JOIN modality_avg ma ON t.Modality = ma.Category WHERE t.SliceThickness IS NOT NULL ) SELECT Category, Entity, Measure, avg_thickness, pct_above_avg, StudyDate, SeriesDescription FROM ranked WHERE rn <= 3;
WITH yearly_avg AS ( SELECT Modality AS Category, EXTRACT(YEAR FROM AcquisitionDate) AS Year, AVG(SliceThickness) AS avg_thickness FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 GROUP BY Modality, EXTRACT(YEAR FROM AcquisitionDate) ), above_avg AS ( SELECT t.Modality AS Category, t.PatientID AS Entity, EXTRACT(YEAR FROM t.AcquisitionDate) AS Year, t.SliceThickness AS Measure, CASE WHEN t.SliceThickness > ya.avg_thickness THEN 1 ELSE 0 END AS above FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 t JOIN yearly_avg ya ON t.Modality = ya.Category AND EXTRACT(YEAR FROM t.AcquisitionDate) = ya.Year ), consecutive AS ( SELECT Category, Entity, Year, above, LAG(above) OVER (PARTITION BY Category, Entity ORDER BY Year) AS prev_above FROM above_avg ) SELECT DISTINCT Category, Entity FROM consecutive WHERE above = 1 AND prev_above = 1;
SELECT DISTINCT Population_ID FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_METADATA m WHERE NOT EXISTS ( SELECT 1 FROM HUMAN_GENOME_VARIANTS.SIMONS_GENOME_DIVERSITY_PROJECT_SAMPLE_ATTRIBUTES a WHERE a.population = m.Population_ID );
WITH base AS ( SELECT PatientID AS Entity, AcquisitionDate AS Time, SliceThickness AS Measure, LAG(SliceThickness, 1) OVER (PARTITION BY PatientID ORDER BY AcquisitionDate) AS prev1, LAG(SliceThickness, 2) OVER (PARTITION BY PatientID ORDER BY AcquisitionDate) AS prev2 FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 WHERE AcquisitionDate IS NOT NULL AND SliceThickness IS NOT NULL ) SELECT DISTINCT Entity FROM base WHERE prev2 IS NOT NULL AND Measure > prev1 AND prev1 > prev2;
WITH sorted_values AS ( SELECT Modality, SliceThickness FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 ORDER BY Modality, SliceThickness ), category_arrays AS ( SELECT Modality, JSON_ARRAYAGG(SliceThickness) AS values_array, COUNT(*) AS cnt FROM sorted_values GROUP BY Modality ), category_median AS ( SELECT Modality, IF( ABS((cnt-1)*0.5 - FLOOR((cnt-1)*0.5)) < 1e-9, JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.5), ']')), JSON_EXTRACT(values_array, CONCAT('$[', FLOOR((cnt-1)*0.5), ']')) * (1 - ((cnt-1)*0.5 - FLOOR((cnt-1)*0.5))) + JSON_EXTRACT(values_array, CONCAT('$[', CEIL((cnt-1)*0.5), ']')) * (((cnt-1)*0.5 - FLOOR((cnt-1)*0.5))) ) AS median_thickness FROM category_arrays ) SELECT t.Modality, t.PatientID, t.SliceThickness FROM TCGA_MITELMAN.TCGA_VERSIONED_RADIOLOGY_IMAGES_TCIA_2018_06 t JOIN category_median m ON t.Modality = m.Modality WHERE t.SliceThickness > m.median_thickness;
WITH lagged AS ( SELECT usertype AS Category, start_station_name AS Entity, starttime AS Time, tripduration AS Measure, LAG(tripduration) OVER (PARTITION BY usertype, start_station_name ORDER BY starttime) AS prev_measure FROM NEW_YORK_CITIBIKE_1.NEW_YORK_CITIBIKE_CITIBIKE_TRIPS WHERE tripduration IS NOT NULL AND starttime IS NOT NULL ), growth AS ( SELECT Category, Entity, Time, (Measure - prev_measure) / NULLIF(prev_measure, 0) * 100 AS growth_rate FROM lagged WHERE prev_measure IS NOT NULL AND prev_measure > 0 ), ranked AS ( SELECT Category, Entity, growth_rate, ROW_NUMBER() OVER (PARTITION BY Category ORDER BY growth_rate DESC) AS rn FROM growth ) SELECT Category, Entity, growth_rate FROM ranked WHERE rn <= 5;
WITH yearly_avg AS ( SELECT Modality AS Category, EXTRACT(YEAR FROM StudyDate) AS Year, AVG(SliceThickness) AS avg_thickness FROM IDC.IDC_V17_DICOM_PIVOT GROUP BY Modality, EXTRACT(YEAR FROM StudyDate) ), above_avg AS ( SELECT t.Modality AS Category, t.PatientID AS Entity, EXTRACT(YEAR FROM t.StudyDate) AS Year, t.SliceThickness AS Measure, CASE WHEN t.SliceThickness > ya.avg_thickness THEN 1 ELSE 0 END AS above FROM IDC.IDC_V17_DICOM_PIVOT t JOIN yearly_avg ya ON t.Modality = ya.Category AND EXTRACT(YEAR FROM t.StudyDate) = ya.Year ), consecutive AS ( SELECT Category, Entity, Year, above, LAG(above) OVER (PARTITION BY Category, Entity ORDER BY Year) AS prev_above FROM above_avg ) SELECT DISTINCT Category, Entity FROM consecutive WHERE above = 1 AND prev_above = 1;
